// Tier 1 catalogues.
//
// The financial terms here are the glossary, not ordinary interface copy.
// "Pending", "frozen", "available" and "settled" carry meaning a central bank
// will hold you to, and a translator rendering "pending" as something closer to
// "maybe" ships a legally different product. These are translated once,
// accountably, and locked. Community contribution applies to everything else.

