/** Locales shipped today. Tier 2 arrives through contribution. */
export const AVAILABLE = ['en', 'fr', 'ar', 'pt', 'sw'];

export function registerAll(): void {
  register('en', en);
  register('fr', fr);
  register('ar', ar);
  register('pt', pt);
  register('sw', sw);
}
